INSERT INTO `exercicioclasse` VALUES (15,20,20,'Ponto','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Ponto {\r\n   private int x, y;\r\n   \r\n   public Ponto ( ) {\r\n       x = y = 0;\r\n   }\r\n   \r\n   public Ponto (int x, int y) {\r\n       this.x = x;\r\n       this.y = y;\r\n   }\r\n   \r\n   public int getX ( ) {\r\n       return x;\r\n   }\r\n   \r\n   public int getY ( ) {\r\n       return y;\r\n   }\r\n   \r\n   public void setX (int x) {\r\n       this.x = x;\r\n   }\r\n   \r\n   public void setY (int y) {\r\n       this.y = y;\r\n   }\r\n   \r\n   public String toString ( ) {\r\n       return \"(\" + x + \", \" + y + \")\";\r\n   }\r\n}','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Ponto {\r\n   private int x, y;\r\n   \r\n   public Ponto ( ) {\r\n       x = y = 0;\r\n   }\r\n   \r\n   public Ponto (int x, int y) {\r\n       this.x = x;\r\n       this.y = y;\r\n   }\r\n   \r\n   public getX ( ) {\r\n       return x;\r\n   }\r\n   \r\n   public getY ( ) {\r\n       return y;\r\n   }\r\n   \r\n   public setX (int x) {\r\n       this.x = x;\r\n   }\r\n   \r\n   public setY (int y) {\r\n       this.y = y;\r\n   }\r\n   \r\n   public String toString ( ) {\r\n       return \"(\" + x + \", \" + y + \")\";\r\n   }\r\n}','2015-05-08 17:54:14',0),(16,20,20,'Reta','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Reta {\r\n   private Ponto p, q;\r\n   \r\n   public Reta ( ) {\r\n       p = q = null;\r\n   }\r\n   \r\n   public Reta (Ponto p, Ponto q) {\r\n       this.p = p;\r\n       this.q = q;\r\n   }\r\n   \r\n   public Ponto getP ( ) {\r\n       return p;\r\n   }\r\n   \r\n   public Ponto getQ ( ) {\r\n       return q;\r\n   }\r\n   \r\n   public void setP (Pont