n(String[] args){\r\n            Teclado teclado = new Teclado();\r\n            char x1 = \' \', x2 = \' \', y1 = \' \' , y2 = \' \';\r\n            while(  x1 != \'S\' && x2 != \'S\' && y1 != \'S\' && y2 != \'S\'){\r\n            x1 = teclado.leChar(\"\\nPonto 1 x: \");\r\n            y1 = teclado.leChar(\"Ponto 1 y: \");\r\n            x2 = teclado.leChar(\"Ponto 2 x: \");\r\n            y2 = teclado.leChar(\"Ponto 1 x: \");\r\n            if(   x1 != \'S\' && x2 != \'S\' && y1 != \'S\' && y2 != \'S\' ){\r\n             Ponto nP1 = new Ponto( Character.getNumericValue(x1) , Character.getNumericValue(y1) );\r\n             Ponto nP2 = new Ponto( Character.getNumericValue(x2) , Character.getNumericValue(y2) );\r\n             Reta reta = new Reta( nP1 , nP2);\r\n             System.out.println(reta.toString());\r\n        }\r\n       }\r\n    }\r\n}\r\n',NULL,'2016-05-07 00:43:26',0),(106,24,32,'NumerosPares','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = \"\";\r\n        int i= 2;\r\n        while( i <= n){\r\n            if (i == 2){\r\n                pares = \"2\";\r\n                }\r\n            else{\r\n                pares = pares + \", \" +i;\r\n            }\r\n            i = i + 2;\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 0;\r\n        while( i <= n){\r\n            soma = soma + i;\r\n                i = i + 1;\r\n            }\r\n        return soma;\r\n    }\r\n}\r\n','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\