n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = \"\";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         s = \"\";\r\n         char c=\' \';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = \"\";\r\n         char c=\' \';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n',NULL,'2016-05-10 22:22:33',0),(131,20,9,'Ponto','\r\n/**\r\n * Write a description of class Ponto here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class Ponto{\r\n    private int x, y;\r\n    \r\n    public Ponto (){\r\n        x = 0;\r\n        y = 0;\r\n    }\r\n    \r\n    public Ponto (int x1 , int y1){\r\n        this.x = x1;\r\n        this.y = y1;\r\n    }\r\n    \r\n    public void setX (int x){\r\n        this.x = x;\r\n    }\r\n    \r\n    public void setY (int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX (){\r\n        return this.x;\r\n    }\r\n    \r\n    public int getY (){\r\n        return this.y;\r\n    }\r\n    \r\n    public String toString (){\r\n        String res = \"(\"+x+\", \" +y+\")\";\r\n        return res;\r\n    }    \r\n        \r\n    \r\n    \r\n        \r\n\r\n\r\n}\r\n',NULL,'2016-05-11 00:12:18',0),(132,20,9,'Reta','\r\n/**\r\n * Write a description of class Reta here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class Reta{\r\n    private Ponto ponto1;\r\n    private Ponto ponto2;\r\n    \r\n    public Reta (Ponto p1 , Ponto p2){\r\n        ponto1 = p1;\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public Reta (){\r\n    }  \r\n    \r\n    public void setPonto1 (Ponto p1){\r\n        ponto1 = p1;\r\n    }\r\n    \r\n    public Ponto getPonto1 (){\r\n        return ponto1;\r\n    }\r\n    \r\n    public void setPonto2 (Ponto p2){\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public Ponto getPonto2 (){\r\n        return ponto2;\r\n    }\r\n    \r\n    public double getDistancia (){\r\n        double c1 =ponto2.getX() - ponto1.getX();\r\n        double c2 =ponto2.getY() - ponto1.getY();\r\n        double b1 = 0;\r\n        double b2 = 0;\r\n        b1 = Math.pow (c1,2);\r\n        b2 = Math.pow (c2,2); \r\n        double d = 0;\r\n        double j = 0;\r\n        j = b1 + b2;\r\n        d = Math.sqrt (j);\r\n        return d;\r\n    }\r\n    \r\n    public String toString (){\r\n    String res = \"(\"+ponto1.getX()+\",\"+ponto1.getY()+\")\";\r\n    res += \"\\n(\"+ponto2.getX()+\",\"+ponto2.getY()+\")\";\r\n    res += \"\\nA distÃ¢ncia entre os pontos Ã©: \" +getDistancia();\r\n    \r\n    return res;\r\n}\r\n\r\n \r\n}    \r\n        \r\n    \r\n    \r\n        \r\n    \r\n    \r\n        \r\n        \r\n    \r\n    \r\n    \r\n\r\n\r\n',NULL,'2016-05-11 00:12:30',0),(133,20,9,'Teclado',' \r\n\r\nimport java.io.*;\r\n\r\n/** Class