( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = \"\";\r\n        int i= 2;\r\n        while( i <= n){\r\n            if (i == 2){\r\n                pares = \"2\";\r\n                }\r\n            else{\r\n                pares = pares + \", \" +i;\r\n            }\r\n            i = i + 2;\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 0;\r\n        while( i <= n){\r\n            soma = soma + i;\r\n                i = i + 1;\r\n            }\r\n        return soma;\r\n    }\r\n}\r\n',NULL,'2016-05-11 00:14:58',0),(136,27,9,'Imprime','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Imprime\r\n{\r\n   // Coloque aqui o seu cÃ³digo\r\n   \r\n   public void imprimeTexto()\r\n   {\r\n        Scanner in = new Scanner(System.in);\r\n        \r\n        for(int i=0;i<10;i++)\r\n        {\r\n            int readed = in.nextInt();\r\n            \r\n            if((readed  % 2) == 0)  \r\n                System.out.println(\"par\");\r\n            else \r\n                System.out.println(\"impar\");\r\n        \r\n        }\r\n   }\r\n}','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Imprime\r\n{\r\n   // Coloque aqui o seu cÃ³digo\r\n   \r\n   public void imprimeTexto()\r\n   {\r\n        Scanner in = new Scanner(System.in);\r\n        \r\n        for(int i=0;i<10;i++)\r\n        {\r\n            int readed = in.nextInt();\r\n            \r\n            if((readed  % 2) == 0)  \r\n                System.out.println(\"par\");\r\n            else \r\n                System.out.println(\"impar\");\r\n        \r\n        }\r\n   }\r\n}','2016-05-11 00:26:43',0),(137,27,9,'Main','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\