   @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser inteiro: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \"+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser inteiro: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser numero: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser numero: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         s = \"\";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = \"\";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         s = \"\";\r\n         char c=\' \';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = \"\";\r\n         char c=\' \';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n',NULL,'2016-05-13 16:14:57',0),(160,20,49,'TestaReta','public class TestaReta {\r\n    public static void main (String args[]) {\r\n        Teclado t = new Teclado();\r\n        int x1 = 0, y1 = 0, x2 = 0, y2 = 0;\r\n        Ponto p1, p2;\r\n        Reta r;\r\n        char c = \' \';           \r\n        while (c!=\'S\' && c!=\'s\') {\r\n            x1 = t.leInt(\"Digite a coordenada X do primeiro ponto da reta\");\r\n            y1 = t.leInt(\"Digite a coordenada Y do primeiro ponto da reta\");\r\n            x2 = t.leInt(\"Digite a coordenada X do segundo ponto da reta\");\r\n            y2 = t.leInt(\"Digite a coordenada Y do segundo ponto da reta\");\r\n            p1 = new Ponto(x1,y1);\r\n            p2 = new Ponto(x2,y2);\r\n            r = new Reta(p1,p2);\r\n            System.out.println (r);\r\n            c = t.leChar(\"Deseja sair do programa?(digite S ou s para sair, digite qualquer outro caracter para continuar)\");\r\n        }\r\n    }\r\n}',NULL,'2016-05-13 16:15:02',0),(161,24,49,'NumerosPares','public class NumerosPares {\r\n    private int n;\r\n    \r\n    public NumerosPares () {\r\n        n = 0;\r\n    }\r\n    \r\n    public NumerosPares (int n) {\r\n        this.n = n;\r\n    }\r\n    \r\n    public void setN (int n) {\r\n        this.n = n;\r\n    }\r\n    \r\n    public int getN () {\r\n        return n;\r\n    }\r\n    \r\n    public String geraPares () {\r\n        String res = \"\";\r\n        int cont = n;\r\n        int teste = cont%2;\r\n        if (teste !=0) {\r\n            cont--;\r\n        }\r\n        while (cont>0) {\r\n            if (cont!=n) {\r\n                res = cont+\", \"+res;\r\n            }\r\n            else{\r\n                res += cont;\r\n            }\r\n            cont -=2;\r\n        }\r\n        return res;\r\n    }\r\n    \r\n    public int somaNumeros () {\r\n        int soma = 0;\r\n        int teste = n%2;\r\n        int m = 0; //usado caso n seja impar\r\n        int i = 0; //Ã­ndice da multiplicaÃ§Ã£o\r\n        int b = 0; // base da soma\r\n        if (teste==0) {\r\n            i = n / 2; \r\n            b = n + 1;\r\n            soma = b * i;\r\n        }\r\n        else {\r\n            m = n - 1;\r\n            b = m + 1;\r\n            i = m / 2;\r\n            soma = b * i + n;\r\n        }\r\n        return soma;\r\n    }\r\n}',NULL,'2016-05-13 16:15:19',0),(162,20,40,'Reta','public class Reta{\r\n    private Ponto ponto1, ponto2;\r\n    \r\n    public Reta(){\r\n        ponto1 = new Ponto();\r\n        ponto2 = new Ponto();\r\n    }\r\n    public Reta(Ponto p1, Ponto p2){\r\n        ponto1 = p1;\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public void setPonto1(Ponto p1){\r\n        ponto1 = p1;\r\n    }\r\n     public void setPonto2(Ponto p2){\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public Ponto getPonto1(){\r\n        return ponto1;\r\n    }\r\n    public Ponto getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n    public double getDistancia(){\r\n        double par1 = (ponto2.getX() - ponto1.getX());\r\n        double par2 = (ponto2.getY() - ponto1.getY());\r\n        double contIncomp = (Math.pow(par1, 2)) + (Math.pow(par2, 2));\r\n        double contCompl = Math.sqrt(contIncomp);\r\n        return contCompl;\r\n    }\r\n    \r\n    public String toString(){\r\n        String str = \"\\n DistÃ¢ncia entre os dois pontos: \" + getDistancia();\r\n        return str;\r\n    }\r\n}',NULL,'2016-05-13 16:38:14',0),(163,20,40,'TestaReta','public class TestaReta{\r\n    public static void main(String[] args){\r\n        Teclado t = new Teclado();\r\n        String opc = \"\";\r\n        \r\n        while(!(opc.equalsIgnoreCase(\"s\"))){\r\n            System.out.println(\"Digite a coordenada X do ponto 1\");\r\n            int x1 = t.leInt();\r\n            System.out.println(\"Digite a coordenada Y do ponto 1\");\r\n            int y1 = t.leInt();\r\n            Ponto p1 = new Ponto(x1, y1);\r\n            System.out.println(\"Digite a coordenada X do ponto 2\");\r\n            int x2 = t.leInt();\r\n            System.out.println(\"Digite a coordenada Y do ponto 2\");\r\n            int y2 = t.leInt();\r\n            Ponto p2 = new Ponto(x2, y2);\r\n            \r\n            Reta r1 = new Reta(p1, p2); \r\n            \r\n            System.out.println(r1.toString());\r\n            System.out.println(\"\");\r\n            \r\n            System.out.println(\"VocÃª quer sair? [Digite \'S\' para sair]\");\r\n            opc = t.leString();\r\n        }\r\n    }\r\n}',NULL,'2016-05-13 16:38:24',0),(164,20,31,'Reta','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe Reta aqui.\r\n * \r\n * @author (Augusto Dal Ago Richter) \r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\npublic class Reta\r\n{\r\n   private Ponto ponto1;\r\n   private Ponto ponto2;\r\n   \r\n   public Reta(Ponto p1, Ponto p2){\r\n       this.ponto1 = p1;\r\n       this.ponto2 = p2;\r\n   }\r\n   \r\n   public Reta(){\r\n       this.ponto1 = null;\r\n       this.ponto2 = null;\r\n    }\r\n    \r\n   public void setPonto1(Ponto p1){\r\n       this.ponto1 = p1;\r\n    }\r\n    \r\n    public void setPonto2(Ponto p2){\r\n        this.ponto2 = p2;\r\n    }\r\n    \r\n    public Ponto getPonto1(){\r\n        return ponto1;\r\n    }\r\n    \r\n    public Ponto getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n    public double getDistancia(){\r\n        double calculo = Math.pow((ponto2.getX() - ponto1.getX()),2) + Math.pow((ponto2.getY() - ponto1.getY()),2);\r\n        double raiz = Math.sqrt(calculo);\r\n        return raiz;\r\n    }