\r\npublic class Tabuada {\r\n    private int numero;\r\n    \r\n    public Tabuada(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada(){\r\n        numero = 0;\r\n    }\r\n    \r\n    public void setNumero(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public int getNumero(){\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada(){\r\n        String ret = \"\";\r\n        for(int i = 1; i<=10; i++){\r\n            ret += numero + \" x \" + i + \" = \" + (numero*i)+ \"\\n\";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n   ',NULL,'2016-05-14 00:10:45',0),(202,26,39,'TestaTabuada','\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 13/05/2016\r\n */\r\npublic class TestaTabuada{\r\n    public static void main(String args[]){\r\n        Teclado t = new Teclado();\r\n        int i = 0;\r\n        while(i != -1){ \r\n            i = t.leInt(\"Digite um numero ou -1 para sair\");\r\n            if(i != -1){\r\n            Tabuada a = new Tabuada(i);\r\n            System.out.println(a.calculaTabuada()); \r\n           }\r\n        \r\n        }\r\n    }\r\n}\r\n    ',NULL,'2016-05-14 00:13:02',0),(204,26,49,'Teclado',' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n   