enho','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe Desenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    public  String desenhaLinha(int  comp) {\r\n        String ret = \"\";\r\n        \r\n        for (int i=1; i<= comp; i++) {\r\n            ret = ret + simbolo;\r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int nroLinhas) {\r\n        String ret = \"\";\r\n        \r\n        for (int i=1; i<= nroLinhas; i++) {\r\n            ret = ret + desenhaLinha (i)+\"\\n\";\r\n        }\r\n        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado (int nroLinhas){\r\n        String ret = \"\";\r\n        \r\n        for ( int i = 1; i <= nroLinhas ; i++){\r\n            ret = ret + desenhaLinha(nroLinhas)+ \"\\n\";\r\n        }\r\n        return  ret;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada (int comp){\r\n        String ret = \"\";\r\n        for (int i = 1; i <= comp ; i++){\r\n            if (i == 1 || i == comp){\r\n                ret = ret + simbolo;\r\n            }\r\n            \r\n            else{\r\n                ret = ret + \" \";\r\n            }\r\n            \r\n        } \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado (int nroLinhas){\r\n        String ret = \"\";\r\n        for (int i = 1 ; i <= nroLinhas ; i++){\r\n        if ( i == 1 || i == nroLinhas){\r\n            ret = ret + desenhaLinha(nroLinhas)+ \"\\n\";\r\n        }\r\n        \r\n        else{\r\n            ret = ret + desenhaLinhaVazada(nroLinhas)+\"\\n\";\r\n        }\r\n    }\r\n    \r\n    \r\n        return ret;\r\n    }\r\n    \r\n   \r\n        \r\n        \r\n        \r\n}\r\n',NULL,'2016-05-14 00:17:33',0),(211,25,45,'Desenho','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe Desenho aqui.\r\n * \r\n * @author (Mateus Hoff) \r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\npublic class Desenho{\r\n    private String simbolo;\r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    public String getSimbolo(){\r\n        return simbolo;\r\n    }\r\n    public String desenhaLinha(int comp){\r\n      String ret =\"\"; \r\n      for (int i = 1; i <= comp; i++){\r\n          ret = ret+simbolo;\r\n      }\r\n      return ret;\r\n    }\r\n    public String desenhaTriangulo(int nroLinhas){\r\n        String ret =\"\";\r\n        for(int i = 1; i<= nroLinhas; i++){\r\n            ret = ret +desenhaLinha(i)+\"\\n\";\r\n        }\r\n        return ret;\r\n    }\r\n    public String desenhaQuadrado(int nroLinhas){\r\n        String ret = \"\";\r\n        for(int i = 1; i <= nroLinhas ; i++){\r\n            \r\n            ret = ret + desenhaLinha(nroLinhas)+\"\\n\";\r\n        }\r\n        return ret;\r\n        \r\n    }\r\n    public String desenhaLinhaVazada(int comp){\r\n    String ret = \"\";\r\n        for(int i = 1; i <= comp; i++){\r\n            if( i == 1 || i == comp)\r\n                ret = ret + simbolo;\r\n        else \r\n         ret = ret+\" \";\r\n    }\r\n    return ret;\r\n    }\r\n    public String desenhaQuadradoVazado(int nroLinhas){\r\n        String ret = \"\";\r\n        for(int i = 1; i <= nroLinhas; i++){\r\n            if(i == 1 || i == nroLinhas)\r\n            ret = ret + desenhaLinha(nroLinhas)+\"\\n\";\r\n            else \r\n            ret = ret + desenhaLinhaVazada(nroLinhas)+\"\\n\";\r\n        }\r\n        return ret;\r\n        \r\n    }\r\n}',NULL,'2016-05-14 00:17:59',0