o (int linhas) {\r\n        String ret = \"\";\r\n        for (int i=1; i<=linhas; i++) {\r\n            if (i==1 || i==linhas) {\r\n                ret = ret + desenhaLinha(linhas) + \"\\n\";\r\n            }\r\n            else {\r\n                ret = ret + desenhaLinhaVazada(linhas) + \"\\n\";\r\n            }                         \r\n        }        \r\n        return ret;\r\n    }\r\n	public String desenhaQuadrado (int linhas) {\r\n		String ret = \"\";\r\n		for (int i=1; i<=linhas; i++) {\r\n			ret = ret + desenhaLinha(linhas) + \"\\n\";\r\n		}\r\n		return ret;\r\n	}\r\n}',NULL,'2016-05-14 00:18:42',0),(216,26,48,'Tabuada','/**\r\n * @author Rodrigo Brandt\r\n * @version 13/05/16\r\n */\r\n\r\npublic class Tabuada{\r\n    \r\n    // atributo\r\n    private int numero;\r\n    \r\n    // construtor\r\n    public Tabuada(int n){\r\n        this.numero = n;\r\n    }\r\n    \r\n    // construtor default\r\n    public Tabuada(){\r\n        this.numero = 0;\r\n    }\r\n    \r\n    // get\r\n    public int getNumero(){\r\n        return numero;\r\n    }\r\n    \r\n    // set\r\n    public void setNumero(int n){\r\n        this.numero = n;\r\n    }\r\n    \r\n    //  Esse  mÃ©todo  irÃ¡  calcular  e  retornar  uma  String  contendo  a  tabuada  para  o  nÃºmero  guardado  no  atributo\r\n    public String calculaTabuada(){\r\n        String tabuada = \"\";\r\n        for (int i = 1; i <= 10; i++){\r\n            tabuada += (numero+\" x \"+i+\" = \"+(numero*i)+\"\\n\");\r\n        }\r\n        return tabuada;\r\n    }\r\n}\r\n',NULL,'2016-05-14 00:19:54',0),(218,26,49,'TestaTabuada','public class TestaTabuada {\r\n    public static void main (String args[]) {\r\n        Teclado t = new Teclado();\r\n        Tabuada t1 = new Tabuada();\r\n        int i = 0;\r\n        while(i!=-1){\r\n            i=t.leInt(\"Digite um numero ou -1 para sair\");\r\n            if (i!=-1) {\r\n                t1 = new Tabuada(i);\r\n                System.out.println(t1.calculaTabuada());\r\n            }\r\n        }        \r\n    }\r\n}',NULL,'2016-05-14 00:21:19',0),(220,26,49,'Tabuada','public class Tabuada {\r\n    private int numero;\r\n    \r\n    public Tabuada (int numero) {\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada () {\r\n        this.numero = 0;\r\n    }    \r\n    \r\n    public void setNumero (int numero) {\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public int getNumero () {\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada() {\r\n        String ret = \"\";\r\n        int res = 0;\r\n        for (int i=1; i<=10; i++) {\r\n            res = numero * i;\r\n            ret = ret+numero+\" x \"+i+\" = \"+res+\"\\n\";\r\n        }        \r\n        return ret;\r\n    }\r\n}','public class Tabuada {\r\n    private int numero;\r\n    \r\n    public Tabuada (int numero) {\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada () {\r\n        this.numero = 0;\r\n    }    \r\n    \r\n    public void setNumero (int numero) {\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public int getNumero () {\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada() {\r\n        String ret = \"\";\r\n        int res = 0;\r\n        for (int i=1; i<=10; i++) {\r\n            res = numero * i;\r\n            ret = ret+numero+\"x\"+i+\"=\"+res+\"\\n\";\r\n        }        \r\n        return ret;\r\n    }\r\n}','2016-05-14 00:28:59',0),(222,25,46,'Desenho','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe Desenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n   \r\n     public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo (){\r\n        return simbolo;\r\n    }\r\n    \r\n