   //construtor sem nenhum argumento\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    \r\n    //construtor que inicializa os atributos da classe\r\n    public NumerosPares(int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    //mÃƒÂ©todos de acesso (get)\r\n    public int getN(){\r\n        return n;\r\n    }\r\n\r\n    //mÃƒÂ©todos modificadores(set)\r\n    public void setN(int novoN){\r\n        n = novoN;\r\n    }\r\n	\r\n	public String geraPares(){		\r\n		int inicio = 2;\r\n		String res = \"\";\r\n		\r\n		while(inicio <= n){\r\n			res += inicio + \", \";			\r\n			inicio += 2;\r\n		}		\r\n		res = res.substring(0, res.length()-2);		\r\n		return res;\r\n	}\r\n	\r\n	public int somaNumeros(){\r\n		int soma = 0;\r\n		\r\n		for(int i=1; i<=n; i++){\r\n			soma += i;\r\n		}\r\n		return soma;\r\n	}   \r\n}\r\n',NULL,'2016-05-17 19:17:44',0);
