INSERT INTO `exercicioclasseauxiliar` VALUES (1,20,'Ponto','/**\r\n *\r\n * @author gilvani\r\n */\r\npublic class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return \"(\" + x + \",\" + y + \')\';\r\n    }\r\n}\r\n',0),(2,20,'Reta','public class Reta {\n\n    private Ponto ponto1;\n    private Ponto ponto2;\n\n    public Reta() {\n    }\n\n    public Reta(Ponto p, Ponto q) {\n        this.ponto1 = p;\n        this.ponto2 = q;\n    }\n\n    public Ponto getPonto1() {\n        return ponto1;\n    }\n\n    public void setPonto1(Ponto p) {\n        this.ponto1 = p;\n    }\n\n    public Ponto getPonto2() {\n        return ponto2;\n    }\n\n    public void setPonto2(Ponto q) {\n        this.ponto2 = q;\n    }\n\n    public double getDistancia() {\n        double x = Math.pow(ponto2.getX() - ponto1.getX(), 2);\n        double y = Math.pow(ponto2.getY() - ponto1.getY(), 2);\n        return Math.sqrt(x + y);\n    }\n    \n    public String toString () {\n        String str = \"\";\n        str = \"\\nPonto 1: \"+ ponto1.toString();\n        str += \"\\nPonto 2: \"+ ponto2.toString();\n        str += \"\\nDistÃ¢ncia entre os pontos: \"+ getDistancia() + \"\\n\";\n        return str;\n    }\n}\n\n',0),(3,21,'Ponto','public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return \"(\" + x + \", \" + y + \')\';\r\n    }\r\n}\r\n',1),(4,21,'ArrayDePontos','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n\r\n    private Ponto[] pontos;\r\n    private int tamanho;\r\n\r\n    public ArrayDePontos(int capacidade) {\r\n\r\n        this.tamanho = 0;\r\n        this.pontos = new Ponto[capacidade];\r\n    }\r\n\r\n    public int getTamanho() {\r\n        return this.tamanho;\r\n    }\r\n\r\n    public void inserirPonto(Ponto ponto) {\r\n        this.pontos[tamanho] = ponto;\r\n        this.tamanho++;\r\n    }\r\n\r\n    public Ponto obtemPontoSuperior() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto superior = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getY() > superior.getY()) {\r\n                superior = this.pontos[i];\r\n            }\r\n        }\r\n        return superior;\r\n    }\r\n\r\n    public Ponto obtemPontoInferior() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto inferior = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getY() < inferior.getY()) {\r\n                inferior = this.pontos[i];\r\n            }\r\n        }\r\n        return inferior;\r\n    }\r\n\r\n    public Ponto obtemPontoMaisADireita() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto direita = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getX() > direita.getX()) {\r\n                direita = this.pontos[i];\r\n            }\r\n        }\r\n        return direita;\r\n    }\r\n\r\n    public Ponto obtemPontoMaisAEsquerda() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto esquerda = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getX() < esquerda.getX()) {\r\n                esquerda = this.pontos[i];\r\n            }\r\n        }\r\n        return esquerda;\r\n    }\r\n}\r\n',0),(5,22,'Socio','public class Socio {\r\n\r\n    private int numero;\r\n    private int idade;\r\n    private String nome;\r\n\r\n    public Socio() {\r\n        this.numero = 0;\r\n        this.idade = 0;\r\n        this.nome = \"\";\r\n    }\r\n\r\n    public Socio(int numero, int idade, String nome) {\r\n        this.numero = numero;\r\n        this.idade = idade;\r\n        this.nome = nome;\r\n    }\r\n\r\n    public int getNumero() {\r\n        return numero;\r\n    }\r\n\r\n    public void setNumero(int numero) {\r\n        this.numero = numero;\r\n    }\r\n\r\n    public int getIdade() {\r\n        return idade;\r\n    }\r\n\r\n    public void setIdade(int idade) {\r\n        this.idade = idade;\r\n    }\r\n\r\n    public String getNome() {\r\n        return nome;\r\n    }\r\n\r\n    public void setNome(String nome) {\r\n        this.nome = nome;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return numero + \", \" + idade + \", \" + nome;\r\n    }\r\n\r\n}\r\n',0),(6,22,'SocioAtleta','public class SocioAtleta extends Socio {\r\n\r\n    private String categoria;\r\n\r\n    public SocioAtleta() {\r\n        super();\r\n    }\r\n\r\n    public SocioAtleta(int numero, int idade, String nome) {\r\n        super(numero, idade, nome);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    @Override\r\n    public void setIdade(int idade) {\r\n        super.setIdade(idade);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    private void atualizaCategoria() {\r\n\r\n        if (this.getIdade() <= 10) {\r\n            this.categoria = \"Mirim\";\r\n        } else if (this.getIdade() <= 15) {\r\n            this.categoria = \"Infantil\";\r\n        } else if (this.getIdade() <= 20) {\r\n            this.categoria = \"Juvenil\";\r\n        } else if (this.getIdade() <= 40) {\r\n            this.categoria = \"Adulto\";\r\n        } else {\r\n            this.categoria = \"Master\";\r\n        }\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return super.toString() + \", \" + categoria;\r\n    }\r\n\r\n}\r\n',0),(12,24,'NumerosPares','\npublic class NumerosPares\n{\n    // instance variables - replace the example below with your own\n    private int n;\n\n    /**\n     * Constructor for objects of class NumerosPares\n     */\n    public NumerosPares()\n    {\n        // initialise instance variables\n        n = 0;\n    }\n    \n    public NumerosPares(int n)\n    {\n        // initialise instance variables\n        this.n = n;\n    }\n    \n    public void setN (int n) {\n        this.n = n;\n    }\n    \n    public int getN() {\n        return n;\n    }\n    \n    public String geraPares (){\n        String str = \"\";\n        int cont = 1;\n        while (cont<=n){\n            if (cont % 2 ==0 && cont!=n)\n                str += cont + \", \";\n                else if (cont % 2 ==0)\n                str += cont;\n            cont++;\n        }\n        return str;\n    }\n    \n    public int  somaNumeros (){\n        int cont = 1, soma = 0;\n        while (cont<=n){\n            if (cont % 2 ==0)\n                soma += cont;\n            cont++;\n        }\n        return soma;\n    }\n\n    \n}\n',0),(14,25,'Desenho','\n/**\n * Escreva a descriÃ§Ã£o da classe Desenho aqui.\n * \n * @author (seu nome) \n * @version (nÃºmero de versÃ£o ou data)\n */\npublic class Desenho\n{\n    private String simbolo = \"\";\n    \n    public Desenho (String simbolo) {\n        this.simbolo = simbolo;\n    }\n    \n    public void setSimbolo (String simbolo){\n        this.simbolo = simbolo;\n    }\n    \n    public String getSimbolo () {\n        return simbolo;\n    }\n    \n    public String desenhaLinha (int comp) {\n        String desenho = \"\";\n        for (int i = 1; i <= comp; i++)\n            desenho += simbolo; \n        return desenho;\n    }\n    \n    public String desenhaLinhaVazada (int comp) {\n        String desenho = \"\";\n        for (int i = 1; i <= comp; i++)\n            if (i==1 || i==comp)\n                desenho += simbolo;\n            else desenho += \" \"; \n        return desenho;\n    }\n    \n    public String desenhaTriangulo (int nroLinhas) {\n        String ret = \"\";\n        for (int i=1; i<=nroLinhas; i++) {\n            String str = desenhaLinha(i);\n            ret += str + \"\\n\";\n        }\n        return ret;\n    }\n    \n    public String desenhaQuadrado (int nroLinhas) {\n         String ret = \"\";\n         for (int i=1; i<=nroLinhas; i++) {\n                String str = desenhaLinha(nroLinhas);\n                ret += str + \"\\n\";\n         }\n        return ret;\n    }\n    \n    public String desenhaQuadradoVazado (int nroLinhas) {\n         String ret = \"\", str=\"\";\n         for (int i=1; i<=nroLinhas; i++) {\n                if (i==1 || i== nroLinhas) \n                    str = desenhaLinha(nroLinhas);\n                else \n                    str = desenhaLinhaVazada(nroLinhas);\n                ret += str + \"\\n\";\n         }\n        return ret;\n    }\n    \n}\n',0),(15,26,'Tabuada','\n/**\n * Escreva a descriÃ§Ã£o da classe Tabuada aqui.\n * \n * @author (seu nome) \n * @version (nÃºmero de versÃ£o ou data)\n */\npublic class Tabuada\n{\n    // variÃ¡veis de instÃ¢ncia - substitua o exemplo abaixo pelo seu prÃ³prio\n    private int numero;\n\n    /**\n     * COnstrutor para objetos da classe Tabuada\n     */\n    public Tabuada()\n    {\n        // inicializa variÃ¡veis de instÃ¢ncia\n        numero = 0;\n    }\n    \n    public Tabuada(int numero)\n    {\n        // inicializa variÃ¡veis de instÃ¢ncia\n        this.numero = numero;\n    }\n    \n    public void setNumero (int numero){\n         this.numero = numero;\n    }\n    \n    public int getNumero (){\n        return numero;\n    }\n\n    public String calculaTabuada (){\n        String ret = \"\";\n        for (int i=1; i<=10; i++) {\n            ret += numero + \" x \" + i + \" = \"+(numero*i)+\"\\n\";\n        }\n        return ret;\n    }\n}\n',0),(16,26,'Teclado',' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser inteiro: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \"+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser inteiro: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser numero: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser numero: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         s = \"\";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = \"\";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         s = \"\";\r\n         char c=\' \';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = \"\";\r\n         char c=\' \';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n\r\n',0),(17,26,'TestaTabuada','\npublic class TestaTabuada\n{\n    public static void main (String args[]){\n        Teclado teclado = new Teclado();\n        int numParada = \' \';\n        while (numParada!= -1){\n            int num =  teclado.leInt (\"Digite um nÃºmero: \");\n            Tabuada t = new Tabuada (num);\n            System.out.println (t.calculaTabuada());\n            numParada = teclado.leInt(\"Digite qualquer nÃºmero para continuar ou -1 para sair\");\n        }\n    }\n}\n',0),(18,27,'Imprime','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Imprime\r\n{\r\n   // Coloque aqui o seu cÃ³digo\r\n   \r\n   public void imprimeTexto()\r\n   {\r\n        Scanner in = new Scanner(System.in);\r\n        \r\n        for(int i=0;i<10;i++)\r\n        {\r\n            int readed = in.nextInt();\r\n            \r\n            if((readed  % 2) == 0)  \r\n                System.out.println(\"par\");\r\n            else \r\n                System.out.println(\"impar\");\r\n        \r\n        }\r\n   }\r\n}',0),(19,27,'Main','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Main\r\n{\r\n   // Coloque aqui o seu cÃ³digo\r\n   public static void main(String[] args) {\r\n        \r\n        Imprime imprimidor = new Imprime();\r\n        imprimidor.imprimeTexto();\r\n    }\r\n}',0);
