INSERT INTO `exercicioclassemarcacao` VALUES (3,26,16,2,1,0,'','2015-05-14 15:08:12',1,NULL),(4,28,11,1,1,0,'CÃ³digo testado com o Bluej.\nFuncionou da seguinte forma:\n\nInstanciei um objeto \"Ponto\", com nome \"p\", e outro objeto \"Ponto\" com nome \"q\".\nDepois, instanciei um objeto \"Reta\" e atribui os pontos \"p\" e \"q\".\n\nUma outra classe \"Teste\" poderia ter sido feita para automatizar o processo.','2015-05-15 00:31:54',1,NULL),(5,30,23,2,1,0,'','2015-05-15 03:55:57',1,NULL),(6,40,23,2,1,0,'','2015-05-18 19:04:46',1,NULL),(7,45,11,1,1,0,'O conteÃºdo sobre Arrays entrou em \"pauta\" essa semana. Ainda nÃ£o possuo conhecimento para executar o exercÃ­cio.','2015-05-21 03:19:08',1,NULL),(8,68,19,2,1,0,'','2015-05-29 05:54:38',1,NULL),(9,97,28,2,30,0,'','2016-05-06 21:20:16',1,NULL),(11,242,30,2,1,0,'','2016-05-17 11:05:27',1,NULL);
