INSERT INTO `exerciciosolucaoclasse` VALUES (26,16,'Ponto','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Ponto {\r\n   private int x, y;\r\n   \r\n   public Ponto ( ) {\r\n       x = y = 0;\r\n   }\r\n   \r\n   public Ponto (int x, int y) {\r\n       this.x = x;\r\n       this.y = y;\r\n   }\r\n   \r\n   public int getX ( ) {\r\n       return x;\r\n   }\r\n   \r\n   public int getY ( ) {\r\n       return y;\r\n   }\r\n   \r\n   public void setX (int x) {\r\n       this.x = x;\r\n   }\r\n   \r\n   public void setY (int y) {\r\n       this.y = y;\r\n   }\r\n   \r\n   public String toString ( ) {\r\n       return \"(\" + x + \", \" + y + \")\";\r\n   }\r\n}'),(27,16,'Reta','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Reta {\r\n   private Ponto p, q;\r\n   \r\n   public Reta ( ) {\r\n       p = q = null;\r\n   }\r\n   \r\n   public Reta (Ponto p, Ponto q) {\r\n       this.p = p;\r\n       this.q = q;\r\n   }\r\n   \r\n   public Ponto getP ( ) {\r\n       return p;\r\n   }\r\n   \r\n   public Ponto getQ ( ) {\r\n       return q;\r\n   }\r\n   \r\n   public void setP (Ponto p) {\r\n       this.p = p;\r\n   }\r\n   \r\n   public void setQ (Ponto q) {\r\n       this.q = q;\r\n   }\r\n   \r\n   public double getDistancia ( ) {\r\n       return Math.sqrt (Math.pow ((q.getX ( ) - p.getX ( )), 2) + Math.pow ((q.getY ( ) - p.getY ( )), 2));\r\n   }\r\n}'),(34,20,'Ponto','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Ponto\r\n{\r\n   private int x;\r\n   private int y;\r\n   \r\n   public Ponto(){}\r\n   \r\n   public Ponto(int x, int y){\r\n       this.x = x;\r\n       this.y = y;\r\n   }\r\n   \r\n   public void setX(int x){\r\n       this.x = x;\r\n   }\r\n   \r\n   public int getX(){\r\n       return this.x;\r\n   }\r\n   \r\n   public void setY(int y){\r\n       this.y = y;\r\n   }\r\n  \r\n   public int getY(){\r\n       return this.y;\r\n   }\r\n   \r\n   public String toString(){\r\n       return \"(\" + this.x + \", \" + this.y + \")\";\r\n   }\r\n}'),(35,20,'Reta','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Reta\r\n{\r\n   private Ponto p;\r\n   private Ponto q;\r\n   \r\n   public Reta(){}\r\n   \r\n   public Reta(Ponto p, Ponto q){\r\n       this.p = p;\r\n       this.q = q;\r\n   }\r\n   \r\n   public void setP(Ponto p){\r\n       this.p = p;\r\n   }\r\n   \r\n   public Ponto getP(){\r\n       return this.p;\r\n   }\r\n   \r\n   public void setQ(Ponto q){\r\n       this.q = q;\r\n   }\r\n   \r\n   public Ponto getQ(){\r\n       return q;\r\n   }\r\n   \r\n   public double getDistancia(){\r\n       return Math.sqrt((Math.pow((q.getX() - p.getX()),2) + Math.pow((q.getY() - p.getY()),2)));\r\n   }\r\n   \r\n}'),(46,26,'Ponto','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Ponto\r\n{\r\n   private int x,y;\r\n   \r\n   public Ponto(){}\r\n   \r\n   public Ponto(int x, int y){\r\n       this.x = x;\r\n       this.y = y;\r\n   }\r\n   \r\n   public void setX(int x){\r\n       this.x = x;\r\n   }\r\n   \r\n   public void setY(int y){\r\n       this.y = y;\r\n   }\r\n   \r\n   public int getX(){\r\n       return this.x;\r\n   }\r\n   \r\n   public int getY(){\r\n       return this.y;\r\n   }\r\n   \r\n   public String toString(){\r\n       return \"(\" + x + \", \" + y + \")\";\r\n   }\r\n}'),(47,26,'Reta','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Reta {\r\n    Ponto p, q;\r\n    \r\n    public Reta(){}\r\n    \r\n    public Reta(Ponto p, Ponto q){\r\n        this.p = p;\r\n        this.q = q;\r\n    }\r\n    \r\n    public void setP(Ponto p){\r\n        this.p = p;\r\n    }\r\n    \r\n    public void setQ(Ponto q){\r\n        this.q = q;\r\n    }\r\n    \r\n    public Ponto getP(){\r\n        return this.p;\r\n    }\r\n    \r\n    public Ponto getQ(){\r\n        return this.q;\r\n    }\r\n   \r\n    public double getDistancia(){\r\n        double distancia =  Math.sqrt(Math.pow((this.q.getX() - this.p.getX()), 2) + Math.pow((this.q.getY() - this.p.getY()), 2));\r\n        return distancia;\r\n    }\r\n}'),(150,78,'Ponto','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Ponto\r\n{\r\n    public static void recursivePrint(int num) {\r\n          System.out.println(\"Number: \" + num);\r\n           \r\n         if(num == 0)\r\n             return;\r\n          else\r\n              recursivePrint(++num);\r\n     }\r\n      \r\n     public static void main(String[] args) {\r\n          Ponto.recursivePrint(1);\r\n     }  \r\n}'),(151,79,'Ponto','\r\n/**\r\n * @author (Delon) \r\n * @version (08/05/2015)\r\n */\r\npublic class Ponto{\r\n    private int x;\r\n    private int y;\r\n    \r\n    //Construtor - Sem argumentos\r\n    public Ponto(){\r\n    }\r\n    \r\n    //Construtor - Com argumentos\r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    //MÃ©todo SET de x\r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n\r\n    //MÃ©todo SET de y\r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    //MÃ©todo GET de x\r\n    public int getX(){\r\n        return this.x;\r\n    }\r\n    \r\n    //MÃ©todo GET de x\r\n    public int getY(){\r\n        return this.y;\r\n    }\r\n    \r\n    //MÃ©todo toString\r\n    public String toString(){\r\n        return \"(\" + this.x + \", \" + this.y + \")\";\r\n    }\r\n}'),(152,79,'Reta','\r\n/**\r\n * @author (Delon) \r\n * @version (14/05/2015)\r\n */\r\npublic class Reta{\r\n    private Ponto p;\r\n    private Ponto q;\r\n    \r\n    //Construtor - Sem argumentos\r\n    public Reta(){\r\n    }\r\n    \r\n    //Construtor - Inicializador\r\n    public Reta(Ponto p, Ponto q){\r\n        this.p = p;\r\n        this.q = q;\r\n    }\r\n    \r\n    //MÃ©todo SET de p\r\n    public void setP(Ponto p){\r\n        this.p = p;\r\n    }\r\n\r\n    //MÃ©todo SET de q\r\n    public void setQ(Ponto q){\r\n        this.q = q;\r\n    }\r\n    \r\n    //MÃ©todo GET de p\r\n    public Ponto getP(){\r\n        return this.p;\r\n    }\r\n    \r\n    //MÃ©todo GET de q\r\n    public Ponto getQ(){\r\n        return this.q;\r\n    }\r\n    \r\n    //MÃ©todo de cÃ¡lculo da distÃ¢ncia\r\n    public double getDistancia(){\r\n        double dist = Math.sqrt((Math.pow((q.getX() - p.getX()),2) + (Math.pow((q.getY() - p.getY()),2))));\r\n		return dist;\r\n    }\r\n}\r\n'),(153,80,'Ponto','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Ponto\r\n{\r\n   private Integer x; \r\n   private Integer y;\r\n   \r\n   public Ponto(){\r\n       \r\n   }\r\n   \r\n    public Ponto(Integer x, Integer y){\r\n       this.x=x;\r\n       this.y=y;\r\n   }\r\n   \r\n   \r\n   public void setX(Integer x){\r\n       this.x=x;\r\n   }\r\n   public void setY(Integer y){\r\n       this.y=y;\r\n   }\r\n   public Integer getX(){\r\n       return this.x;\r\n   }\r\n   public Integer getY(){\r\n       return this.y;\r\n   }\r\n   \r\n   @Override\r\n   public String toString(){\r\n       return \"(\".concat(this.x.toString()).concat(\", \").concat(this.y.toString()).concat(\")\");\r\n       \r\n   }\r\n   \r\n   \r\n   \r\n}'),(154,80,'Reta','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\nimport Ponto;\r\n\r\nclass Reta\r\n{\r\n   private Ponto p; \r\n   private Ponto q;\r\n   \r\n   public Reta(Ponto p, Ponto q){\r\n       \r\n       //Instanciando variÃ¡vel p\r\n       this.p=new Ponto();\r\n       p.setY(p.getY());\r\n       p.setX(p.getX());\r\n       \r\n       //Instanciando variÃ¡velqp\r\n       this.q=new Ponto();\r\n       q.setY(q.getY());\r\n       q.setX(q.getX());\r\n   }\r\n   \r\n   public Reta(){\r\n   }   \r\n    public void setP(Ponto p){\r\n        this.p=p;\r\n    }\r\n    public setQ(Ponto q){\r\n        this.q=q;\r\n    }\r\n    public Ponto getP(){\r\n        return this.p;\r\n    }\r\n    public Ponto getQ(){\r\n         return this.q;\r\n    }\r\n    \r\n    public double getDistancia(){\r\n        \r\n        double raiz = 0;\r\n        \r\n        //calculando lado esquerdo da raiz\r\n        double sub1 = this.q.getX()-this.p.getX();\r\n        double result1 = Math.pow(sub1,2);\r\n        \r\n        //calculando lado direito da raiz\r\n         double sub2 = this.q.getY()-this.p.getY();\r\n        double result1 = Math.pow(sub2,2);\r\n        \r\n        //calculando raiz quadrada\r\n        raiz = Math.sqrt(result1+result2);\r\n        \r\n        \r\n    }\r\n    \r\n   \r\n}\r\n'),(155,81,'Ponto','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Ponto\r\n{\r\n   private Integer x; \r\n   private Integer y;\r\n   \r\n   public Ponto(){\r\n       \r\n   }\r\n   \r\n    public Ponto(Integer x, Integer y){\r\n       this.x=x;\r\n       this.y=y;\r\n   }\r\n   \r\n   \r\n   public void setX(Integer x){\r\n       this.x=x;\r\n   }\r\n   public void setY(Integer y){\r\n       this.y=y;\r\n   }\r\n   public Integer getX(){\r\n       return this.x;\r\n   }\r\n   public Integer getY(){\r\n       return this.y;\r\n   }\r\n   \r\n   @Override\r\n   public String toString(){\r\n       return \"(\".concat(this.x.toString()).concat(\", \").concat(this.y.toString()).concat(\")\");\r\n       \r\n   }\r\n   \r\n   \r\n   \r\n}'),(156,81,'Reta','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\nimport Ponto.*;\r\n\r\nclass Reta\r\n{\r\n   private Ponto p; \r\n   private Ponto q;\r\n   \r\n   public Reta(Ponto p, Ponto q){\r\n       \r\n       //Instanciando variÃ¡vel p\r\n       this.p=new Ponto();\r\n       p.setY(p.getY());\r\n       p.setX(p.getX());\r\n       \r\n       //Instanciando variÃ¡velqp\r\n       this.q=new Ponto();\r\n       q.setY(q.getY());\r\n       q.setX(q.getX());\r\n   }\r\n   \r\n   public Reta(){\r\n   }   \r\n    public void setP(Ponto p){\r\n        this.p=p;\r\n    }\r\n    public setQ(Ponto q){\r\n        this.q=q;\r\n    }\r\n    public Ponto getP(){\r\n        return this.p;\r\n    }\r\n    public Ponto getQ(){\r\n         return this.q;\r\n    }\r\n    \r\n    public double getDistancia(){\r\n        \r\n        double raiz = 0;\r\n        \r\n        //calculando lado esquerdo da raiz\r\n        double sub1 = this.q.getX()-this.p.getX();\r\n        double result1 = Math.pow(sub1,2);\r\n        \r\n        //calculando lado direito da raiz\r\n         double sub2 = this.q.getY()-this.p.getY();\r\n        double result1 = Math.pow(sub2,2);\r\n        \r\n        //calculando raiz quadrada\r\n        raiz = Math.sqrt(result1+result2);\r\n        \r\n        \r\n    }\r\n    \r\n   \r\n}\r\n'),(157,82,'Ponto','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Ponto\r\n{\r\n   private Integer x; \r\n   private Integer y;\r\n   \r\n   public Ponto(){\r\n       \r\n   }\r\n   \r\n    public Ponto(Integer x, Integer y){\r\n       this.x=x;\r\n       this.y=y;\r\n   }\r\n   \r\n   \r\n   public void setX(Integer x){\r\n       this.x=x;\r\n   }\r\n   public void setY(Integer y){\r\n       this.y=y;\r\n   }\r\n   public Integer getX(){\r\n       return this.x;\r\n   }\r\n   pub