rosPares(){\r\n        this.n = 0;\r\n    }\r\n    \r\n    // mÃ©todo construtor 2\r\n    public NumerosPares(int _n){\r\n        this.n = _n;\r\n    }\r\n    \r\n    // esse mÃ©todo retorna uma String com os nÃºmeros positivos pares menores ou igual  a n e maiores que zero\r\n    public String geraPares(){\r\n        String pares = \"\";\r\n        int contador = 1;\r\n        while(contador <= this.n){\r\n            if(contador%2 == 0){\r\n                if(contador == this.n || contador == (this.n-1)){\r\n                    pares += contador;\r\n                } else {\r\n                    pares += contador+\", \";    \r\n                }\r\n            }\r\n            contador++;\r\n        }\r\n        return pares;\r\n    }\r\n    \r\n    // esse mÃ©todo  soma  todos  os  nÃºmeros positivos menores ou igual a n e maiores que zero\r\n    public int somaNumeros(){\r\n        int soma = 0;\r\n        int contador = 1;\r\n        while(contador <= this.n){\r\n            soma += contador;\r\n            contador++;\r\n        }\r\n        return soma;\r\n    }\r\n}\r\n'),(530,279,'NumerosPares','\r\npublic class NumerosPares\r\n{\r\n    // instance variables - replace the example below with your own\r\n    private int n;\r\n\r\n    /**\r\n     * Constructor for objects of class NumerosPares\r\n     */\r\n    public NumerosPares()\r\n    {\r\n        // initialise instance variables\r\n        n = 0;\r\n    }\r\n    \r\n    public NumerosPares(int n)\r\n    {\r\n        // initialise instance variables\r\n        this.n = n;\r\n    }\r\n    \r\n    public void setN (int n) {\r\n        this.n = n;\r\n    }\r\n    \r\n    public int getN() {\r\n        return n;\r\n    }\r\n    \r\n    public String geraPares (){\r\n        String str = \"\";\r\n        int cont = 1;\r\n        while (cont<=n){\r\n            if (cont % 2 ==0 && cont!=n)\r\n                str += cont + \", \";\r\n                else if (cont % 2 ==0)\r\n                str += cont;\r\n    