r\n        this.ponto1 = p;\r\n    }\r\n    \r\n    public void setPonto2(Ponto p){\r\n        this.ponto2 = p;\r\n    }\r\n    \r\n    // mÃ©todo que calcula a distÃ¢ncia entre os pontos da reta\r\n    public double getDistancia(){\r\n        double pre = (Math.pow((ponto2.getX()-ponto1.getX()),2))+(Math.pow((ponto2.getY()-ponto1.getY()),2));\r\n        double distancia = Math.sqrt(pre);\r\n        return distancia;\r\n    }\r\n    \r\n    // mÃ©todo toString\r\n    public String toString(){\r\n        String texto = \"Ponto 1: (\"+ponto1.getX()+\", \"+ponto1.getY()+\")\\nPonto 2: (\"+ponto2.getX()+\", \"+ponto2.getY()+\")\";\r\n        return texto;\r\n    }\r\n    \r\n}\r\n'),(533,280,'Teclado',' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do teclado */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser inteiro: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             Sy