ta {\r\n\r\n    private Ponto p;\r\n    private Ponto q;\r\n\r\n    public Reta() {\r\n    }\r\n\r\n    public Reta(Ponto p, Ponto q) {\r\n        this.p = p;\r\n        this.q = q;\r\n    }\r\n\r\n    public Ponto getP() {\r\n        return p;\r\n    }\r\n\r\n    public void setP(Ponto p) {\r\n        this.p = p;\r\n    }\r\n\r\n    public Ponto getQ() {\r\n        return q;\r\n    }\r\n\r\n    public void setQ(Ponto q) {\r\n        this.q = q;\r\n    }\r\n\r\n    public double getDistancia() {\r\n        double x = Math.pow(q.getX() - p.getX(), 2);\r\n        double y = Math.pow(q.getY() - p.getY(), 2);\r\n        return Math.sqrt(x + y);\r\n    }\r\n}\r\n'),(638,327,'Ponto','public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return \"(\" + x + \", \" + y + \')\';\r\n    }\r\n}\r\n'),(639,328,'Ponto','public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return \"(\" + x + \", \" + y + \')\';\r\n    }\r\n}\r\n'),(640,328,'ArrayDePontos','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n\r\n    private Ponto[] pontos;\r\n    private int tamanho;\r\n\r\n    public ArrayDePontos(int capacidade) {\r\n\r\n        this.tamanho = 0;\r\n        this.pontos = new Ponto[capacidade];\r\n    }\r\n\r\n    public int getTamanho() {\r\n        return this.tamanho;\r\n    }\r\n\r\n    public void inserirPonto(Ponto ponto) {\r\n        this.pontos[tamanho] = ponto;\r\n        this.tamanho++;\r\n    }\r\n\r\n    public Ponto obtemPontoSuperior() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto superior = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getY() > superior.getY()) {\r\n                superior = this.pontos[i];\r\n            }\r\n        }\r\n        return superior;\r\n    }\r\n\r\n    public Ponto obtemPontoInferior() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto inferior = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getY() < inferior.getY()) {\r\n                inferior = this.pontos[i];\r\n            }\r\n        }\r\n        return inferior;\r\n    }\r\n\r\n    public Ponto obtemPontoMaisADireita() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto direita = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getX() > direita.getX()) {\r\n                direita = this.pontos[i];\r\n            }\r\n        }\r\n        return direita;\r\n    }\r\n\r\n    public Ponto obtemPontoMaisAEsquerda() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto esquerda = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getX() < esquerda.getX()) {\r\n                esquerda = this.pontos[i];\r\n            }\r\n        }\r\n        return esquerda;\r\n    }\r\n}\r\n'),(641,329,'Desenho','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe Desenho aqui.\r\n * \r\n * @author aluno\r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo = \"\";\r\n    \r\n    public Desenho (String simbolo) {\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    public String desenhaLinha (int comp) {\r\n        String desenho = \"\";\r\n        for (int i = 1; i <= comp; i++)\r\n            desenho += simbolo; \r\n        return desenho;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada (int comp) {\r\n        String desenho = \"\";\r\n        for (int i = 1; i <= comp; i++)\r\n            if (i==1 || i==comp)\r\n                desenho += simbolo;\r\n            else desenho += \" \"; \r\n        return desenho;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int nroLinhas) {\r\n        String ret = \"\";\r\n        for (int i=1; i<=nroLinhas; i++) {\r\n            String str = desenhaLinha(i);\r\n            ret += str + \"\\n\";\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado (int nroLinhas) {\r\n         String ret = \"\";\r\n         for (int i=1; i<=nroLinhas; i++) {\r\n                String str = desenhaLinha(nroLinhas);\r\n                ret += str + \"\\n\";\r\n         }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado (int nroLinhas) {\r\n         String ret = \"\", str=\"\";\r\n         for (int i=1; i<=nroLinhas; i++) {\r\n                if (i==1 || i== nroLinhas) \r\n                    str = desenhaLinha(nroLinhas);\r\n                else \r\n                    str = desenhaLinhaVazada(nroLinhas);\r\n                ret += str + \"\\n\";\r\n         }\r\n        return ret;\r\n    }\r\n    \r\n}\r\n'),(642,330,'Desenho','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe Desenho aqui.\r\n * \r\n * @author aluno\r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo = \"\";\r\n    \r\n    public Desenho (String simbolo) {\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    /*public String desenhaLinha (int comp) {\r\n        String desenho = \"\";\r\n        for (int i = 1; i <= comp; i++)\r\n            desenho += simbolo; \r\n        return desenho;\r\n    }*/\r\n    \r\n    public String desenhaLinhaVazada (int comp) {\r\n        String desenho = \"\";\r\n        for (int i = 1; i <= comp; i++)\r\n            if (i==1 || i==comp)\r\n                desenho += simbolo;\r\n            else desenho += \" \"; \r\n        return desenho;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int nroLinhas) {\r\n        String ret = \"\";\r\n        for (int i=1; i<=nroLinhas; i++) {\r\n            String str = desenhaLinha(i);\r\n            ret += str + \"\\n\";\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado (int nroLinhas) {\r\n         String ret = \"\";\r\n         for (int i=1; i<=nroLinhas; i++) {\r\n                String str = desenhaLinha(nroLinhas);\r\n                ret += str + \"\\n\";\r\n         }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado (int nroLinhas) {\r\n         String ret = \"\", str=\"\";\r\n         for (int i=1; i<=nroLinhas; i++) {\r\n                if (i==1 || i== nroLinhas) \r\n                    str = desenhaLinha(nroLinhas);\r\n                else \r\n                    str = desenhaLinhaVazada(nroLinhas);\r\n                ret += str + \"\\n\";\r\n         }\r\n        return ret;\r\n    }\r\n    \r\n}\r\n'),(643,331,'NumerosPares','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe NumerosPares aqui.\r\n * \r\n * @author (Mateus Hoff) \r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\n public class NumerosPares{\r\n    private int n;\r\n    public NumerosPares(){\r\n    }\r\n    public NumerosPares(int n){\r\n        this.n = n;\r\n    }\r\n    public void setN(int n){\r\n        this.n = n;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public String geraPares(){\r\n    String par = \"\";\r\n    int cont = 2;\r\n    while(cont <= n ){\r\n    if( cont != n && cont != n-1){\r\n        par = par+cont+\", \";\r\n    } else par = par+cont;\r\n    cont = cont +2;\r\n    }\r\n    return par;\r\n    }\r\n    public int somaNumeros(){\r\n    int soma = 0;\r\n    int cont = 0;\r\n        while(cont <= n){\r\n        if(cont > 0 )\r\n        soma = soma +cont;\r\n        cont++;\r\n    }\r\n    return soma;\r\n    }\r\n    public String toString(){\r\n        String str = \"\\nO NÃºmero Ã©: \"+n;\r\n        str+=\"\\nOs pares sÃ£o: \"+geraPares();\r\n        str+=\"\\nA soma de todos os NÃºmeros Ã©: \"+somaNumeros();\r\n        return str;\r\n    }\r\n}'),(644,331,'TestaPares','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe TestaPares aqui.\r\n * \r\n * @author (Mateus Hoff) \r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\npublic class TestaPares{\r\n    public static void main(String args[]){\r\n     Teclado t = new Teclado();\r\n     int x = 0;\r\n        while(x != -1){\r\n        int n = t.leInt(\"Digite o valor de n: \");\r\n        NumerosPares n1 = new NumerosPares(n);\r\n        System.out.println (n1.toString());\r\n        x = t.leInt(\"Digite -1 para interromper o processo: \");\r\n    }\r\n}\r\n}\r\n\r\n'),(645,331,'Teclado',' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser inteiro: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \"+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser inteiro: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n      