        String valor = \"\";\r\n        \r\n        while ( i <= n && n >= 0){\r\n            if (n % 2 == 0 && i < n){\r\n                valor = valor + i +\", \";\r\n            }\r\n            else if (n % 2 == 0 && i == n){\r\n                valor = valor + i;\r\n            }\r\n            else if (n % 2 != 0 && i < n - 2){\r\n                valor = valor + i + \",\";\r\n            }\r\n            else\r\n            valor = valor + i;\r\n           \r\n            i=i+2;\r\n        }\r\n        return valor;\r\n    }\r\n   \r\n    public int somaNumeros (){\r\n            int i = 1;\r\n        int valor = 0;\r\n        \r\n        while ( i <= n && n >= 0){\r\n            if (n % 2 == 0 && i < n){\r\n                valor = valor + i;\r\n            }\r\n            else if (n % 2 == 0 && i == n){\r\n                valor = valor + i;\r\n            }\r\n            else if (n % 2 != 0 && i < n - 2){\r\n                valor = valor + i;\r\n            }\r\n            else\r\n            valor = valor + i;\r\n           \r\n            i++;\r\n        }\r\n        return valor;\r\n    }\r\n}\r\n                \r\n            \r\n            \r\n            '),(725,368,'Ponto','public class Ponto {\r\n    private int x,y;\r\n    \r\n    public Ponto() {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public void setX (int x){\r\n        this.x = x;\r\n    }\r\n    \r\n    public void setY (int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX (){\r\n        return x;\r\n    }\r\n    \r\n    public int getY (){\r\n        return y;\r\n    }\r\n    \r\n    public String toString() {\r\n        String resultado = \"(\"+x+\", \"+y+\")\";\r\n        return resultado;\r\n    }\r\n\r\n\r\n}\r\n'),(726,368,'Reta','public class Reta{\r\n    private Ponto ponto1;\r\n    private Ponto ponto2;\r\n    \r\n    public Reta (){\r\n 