 int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \"+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser inteiro: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser numero: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser numero: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         s = \"\";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = \"\";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         s = \"\";\r\n         char c=\' \';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = \"\";\r\n         char c=\' \';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),(761,375,'TestaReta','/**\r\n * Write a description of class TestaReta here.\r\n * \r\n * @author VinÃ­cius Mateus Flach\r\n * @version (a version number or a date)\r\n */\r\npublic class TestaReta\r\n{\r\n    public static void main (String args[]){\r\n        Teclado teclado = new T