      return quadrado;\r\n    }\r\n    \r\n    \r\n    \r\n}\r\n'),(802,390,'Desenho','/**\r\n * @author Rodrigo Brandt\r\n * @version 13/05/16\r\n */\r\n\r\npublic class Desenho{\r\n    \r\n    // atributos\r\n    private String simbolo;\r\n    \r\n    // construtor\r\n    public Desenho(String s){\r\n        this.simbolo = s;\r\n    }\r\n    \r\n    // get\r\n    public String getSimbolo(){\r\n        return simbolo;\r\n    }\r\n    \r\n    // set\r\n    public void setSimbolo(String s){\r\n        this.simbolo = s;\r\n    }\r\n    \r\n    \r\n    public String desenhaTriangulo (int linhas){\r\n        String triangulo = \"\";\r\n        for (int i = 1; i <= linhas; i++){\r\n            triangulo += desenhaLinha(i);\r\n        }\r\n        return triangulo;\r\n    }\r\n    \r\n    // Esse mÃ©todo desenha  uma  linha  de  comprimento  comp  e  a  retorna  como  uma String\r\n    public String desenhaLinha (int comp){\r\n        String linha = \"\";\r\n        for (int i = 1; i <= comp; i++){\r\n            linha += simbolo;\r\n        }\r\n        //linha += \"\\n\";\r\n        return linha;\r\n    }\r\n    \r\n    /* Esse mÃ©todo desenha uma linha de  comprimento comp e  a  retorna  como  uma String\r\n     * A  diferenÃ§a  deste mÃ©todo  para  o  mÃ©todo desenhaLinha Ã© que  apenas  o  primeiro  e  Ãºltimo\r\n     * caracteres da linha serÃ£o representados pelo sÃ­mbolo\r\n     */\r\n    public String desenhaLinhaVazada (int comp){\r\n        String linha = simbolo;\r\n        for (int i = 1; i <= (comp-2); i++){\r\n            linha += \" \";\r\n        }\r\n        linha += simbolo;\r\n        linha += \"\\n\";\r\n        return linha;\r\n    }\r\n    \r\n    // Esse mÃ©todo desenha  um  quadrado,  onde  o nÃºmero de linhas do mesmo Ã© passado como parÃ¢metro\r\n    public String desenhaQuadrado (int linhas){\r\n        String quadrado = \"\";\r\n        quadrado += desenhaLinha(linhas);\r\n        for (int i = 1; i <= (linhas-2); i++){\r\n            quadrado += desenhaLinha(linhas);\r\n        }\r\n        quadrado += desenhaLinha(linhas);\r\n        return quadrado;\r\n    }\r\n    \r\n    \r\n    public String desenhaQuadradoVazado (int nroLinhas){\r\n        String quadrado = \"\";\r\n        quadrado += desenhaLinha(nroLinhas);\r\n        for (int i = 1; i <= (nroLinhas-2); i++){\r\n            quadrado += desenhaLinhaVazada(nroLinhas);\r\n        }\r\n        quadrado += desenhaLinha(nroLinhas);\r\n        return quadrado;\r\n    }\r\n    \r\n    \r\n    \r\n}\r\n'),(803,391,'Desenho','/* \r\n * Joice Cazanoski Gomes\r\n * 13/05/2016\r\n */\r\npublic class Desenho{\r\n    private String simbolo;\r\n    \r\n    public Desenho(String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo(String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo(){\r\n        return simbolo;\r\n    }\r\n    \r\n    public String desenhaLinha(int comp){\r\n        String ret = \"\";\r\n        for(int i =1; i <= comp; i++){\r\n            ret += simbolo;\r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaTriangulo(int linhas){\r\n        String ret = \"\";\r\n        for(int i = 1; i<=linhas; i++){\r\n            ret += desenhaLinha(i)+ \"\\n\";\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado(int nroLinhas){\r\n        String ret = \"\";\r\n        for(int i = 1; i <= nroLinhas; i++){\r\n            ret += desenhaLinha(nroLinhas) + \"\\n\";\r\n        }\r\n        System.out.println(ret);\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada(int comp){\r\n        String ret = \"\";\r\n        for (int i = 1; i <= comp; i++){\r\n            if (i == 1 || i == comp)\r\n                ret += simbolo;\r\n            else \r\n                ret += \" \";\r\n        }      \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado(int linhas){\r\n        String ret = \"\";\r\n        for(int i = 1; i<=linhas; i++){\r\n            if(i == 1 || i == linhas)\r\n            ret += desenhaLinha(linhas)+ \"\\n\";\r\n            else\r\n            ret += desenhaLinhaVazada(linhas)+ \"\\n\";\r\n        }\r\n        return ret;\r\n    }\r\n}'),(804,392,'Desenho','/**\r\n * @author Rodrigo Brandt\r\n * @version 13/05/16\r\n */\r\n\r\npublic class Desenho{\r\n    \r\n    // atributos\r\n    private String simbolo;\r\n    \r\n    // construtor\r\n    public Desenho(String s){\r\n        this.simbolo = s;\r\n    }\r\n    \r\n    // get\r\n    public String getSimbolo(){\r\n        return simbolo;\r\n    }\r\n    \r\n    // set\r\n    public void setSimbolo(String s){\r\n        this.simbolo = s;\r\n    }\r\n    \r\n    \r\n    public String desenhaTriangulo (int linhas){\r\n        String triangulo = \"\";\r\n        for (int i = 1; i <= linhas; i++){\r\n            triangulo += desenhaLinha(i);\r\n        }\r\n        return triangulo;\r\n    }\r\n    \r\n    // Esse mÃ©todo desenha  uma  linha  de  comprimento  comp  e  a  retorna  como  uma String\r\n    public String desenhaLinha (int comp){\r\n        String linha = \"\";\r\n        for (int i = 1; i <= comp; i++){\r\n            linha += simbolo;\r\n        }\r\n        //linha += \"\\n\";\r\n        return linha;\r\n    }\r\n    \r\n    /* Esse mÃ©todo desenha uma linha de  comprimento comp e  a  retorna  como  uma String\r\n     * A  diferenÃ§a  deste mÃ©todo  para  o  mÃ©todo desenhaLinha Ã© que  apenas  o  primeiro  e  Ãºltimo\r\n     * caracteres da linha serÃ£o representados pelo sÃ­mbolo\r\n     */\r\n    public String desenhaLinhaVazada (int comp){\r\n        String linha = simbolo;\r\n        for (int i = 1; i <= (comp-2); i++){\r\n            linha += \" \";\r\n        }\r\n        linha += simbolo;\r\n        //linha += \"\\n\";\r\n        return linha;\r\n    }\r\n    \r\n    // Esse mÃ©todo desenha  um  quadrado,  onde  o nÃºmero de linhas do mesmo Ã© passado como parÃ¢metro\r\n    public String desenhaQuadrado (int linhas){\r\n        String quadrado = \"\";\r\n        quadrado += desenhaLinha(linhas);\r\n        for (int i = 1; i <= (linhas-2); i++){\r\n            quadrado += desenhaLinha(linhas);\r\n        }\r\n        quadrado += desenhaLinha(linhas);\r\n        return quadrado;\r\n    }\r\n    \r\n    \r\n    public String desenhaQuadradoVazado (int nroLinhas){\r\n        String quadrado = \"\";\r\n        quadrado += desenhaLinha(nroLinhas);\r\n        for (int i = 1; i <= (nroLinhas-2); i++){\r\n            quadrado += desenhaLinhaVazada(nroLinhas);\r\n        }\r\n        quadrado += desenhaLinha(nroLinhas);\r\n        return quadrado;\r\n    }\r\n    \r\n    \r\n    \r\n}\r\n'),(805,393,'TabuadaSoma','\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 13/05/2016\r\n */\r\npublic class TabuadaSoma {\r\n    private int numero;\r\n    \r\n    public TabuadaSoma(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public TabuadaSoma(){\r\n        numero = 0;\r\n    }\r\n    \r\n    public String calculaTabuada(){\r\n        String ret = \"\";\r\n        for(int i = 1; i<=10; i++){\r\n            ret += numero + \" x \" + i + \" = \" + (numero*i)+ \"\\n\";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n   '),(806,394,'Tabuada','\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 13/05/2016\r\n */\r\npublic class Tabuada {\r\n    private int numero;\r\n    \r\n    public Tabuada(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada(){\r\n        numero = 0;\r\n    }\r\n    \r\n    public String calculaTabuada(){\r\n        String ret = \"\";\r\n        for(int i = 1; i<=10; i++){\r\n            ret += numero + \" x \" + i + \" = \" + (numero*i)+ \"\\n\";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n   '),(807,395,'Desenho','/**\r\n * @author Rodrigo Brandt\r\n * @version 13/05/16\r\n */\r\n\r\npublic class Desenho{\r