olo;\r\n            for (int i=1; i<=(comp-2); i++) {\r\n                ret = ret + \" \";\r\n            }\r\n            ret = ret + simbolo;\r\n        }\r\n        else {\r\n            desenhaLinha(comp);\r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado (int linhas) {\r\n        String ret = \"\";\r\n        for (int i=1; i<=linhas; i++) {\r\n            if (i==1 || i==linhas) {\r\n                ret = ret + desenhaLinha(linhas) + \"\\n\";\r\n            }\r\n            else {\r\n                ret = ret + desenhaLinhaVazada(linhas) + \"\\n\";\r\n            }                         \r\n        }        \r\n        return ret;\r\n    }\r\n	public String desenhaQuadrado (int linhas) {\r\n		String ret = \"\";\r\n		for (int i=1; i<=linhas; i++) {\r\n			ret = ret + desenhaLinha(linhas) + \"\\n\";\r\n		}\r\n	}\r\n}'),(831,408,'Desenho','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe Desenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n   \r\n     public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo (){\r\n        return simbolo;\r\n    }\r\n    \r\n    public String desenhaLinha (int comp) {\r\n        String ret = \"\";\r\n        for (int i=1; i<=comp; i++) {\r\n            ret = ret + simbolo;\r\n        }\r\n        return ret;\r\n    } \r\n   public String desenhaTriangulo (int nroLinhas) {\r\n       String ret = \"\";\r\n       for (int i=1; i<=nroLinhas ; i++) {\r\n        ret = ret + desenhaLinha (i) + \"\\n\";\r\n        } \r\n       return ret;\r\n    } \r\n   public String desenhaLinhaVazada (int nroLinhas) {\r\n       String ret = \"\";\r\n       for (int i=1; i<=nroLinhas; i++) {\r\n        if (i==1 || i==nroLinhas)\r\n        ret = ret + desenhaLinha (1);\r\n        else\r\n        ret = ret + \" \";\r\n    }\r\n    return ret;\r\n    }\r\n   public String desenhaQuadrado (int nroLinhas) {\r\n      String ret = \"\";\r\n    for (int i=1; i<=nroLinhas; i++) {\r\n    if (i==1 || i==nroLinhas)\r\n    ret = ret + desenhaLinha (nroLinhas) + \"\\n\";\r\n    else \r\n    ret = ret + desenhaLinhaVazada (nroLinhas) + \"\\n\";\r\n    }\r\n    return ret;\r\n    }\r\n   }\r\n\r\n\r\n\r\n'),(832,409,'Teclado',' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser inteiro: \"+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \"+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println (\"o valor digitado deve ser inteiro: \"+e );\r\n         }\r\n         return